{
  "project": "cadi-alfa",
  "module": "cooldown_tick",
  "description": "Decrementa en una jornada los cooldowns activos de plantilla, NPC y espacio dentro de MemoryState.",
  "functions": [
    {
      "name": "tick_cooldowns",
      "signature": "fn tick_cooldowns(memory: &mut MemoryState)",
      "description": "Recorre los mapas de cooldown y reduce en 1 los contadores mayores que 0.",
      "examples": [
        "tick_cooldowns(&mut memory);"
      ]
    }
  ],
  "tests": [
    "#[test] fn test_tick_cooldowns_decrements_template_cooldown() { let mut memory = MemoryState::new(); memory.cooldowns_plantilla.insert(\"evt_1\".to_string(), 3); tick_cooldowns(&mut memory); assert_eq!(memory.cooldowns_plantilla.get(\"evt_1\"), Some(&2)); }",
    "#[test] fn test_tick_cooldowns_decrements_npc_and_space_cooldowns() { let mut memory = MemoryState::new(); memory.cooldowns_npc.insert(\"npc_1\".to_string(), 2); memory.cooldowns_espacio.insert(\"cadiz_puerto\".to_string(), 1); tick_cooldowns(&mut memory); assert_eq!(memory.cooldowns_npc.get(\"npc_1\"), Some(&1)); assert_eq!(memory.cooldowns_espacio.get(\"cadiz_puerto\"), Some(&0)); }",
    "#[test] fn test_tick_cooldowns_does_not_make_values_negative() { let mut memory = MemoryState::new(); memory.cooldowns_plantilla.insert(\"evt_1\".to_string(), 0); tick_cooldowns(&mut memory); assert_eq!(memory.cooldowns_plantilla.get(\"evt_1\"), Some(&0)); }",
    "#[test] fn test_tick_cooldowns_leaves_empty_maps_untouched() { let mut memory = MemoryState::new(); tick_cooldowns(&mut memory); assert!(memory.cooldowns_plantilla.is_empty()); assert!(memory.cooldowns_npc.is_empty()); assert!(memory.cooldowns_espacio.is_empty()); }"
  ],
  "dependencies": [],
  "notes": "Importar MemoryState desde crate::memory_state. Implementar fn tick_cooldowns(memory: &mut MemoryState). Debe recorrer los tres mapas: cooldowns_plantilla, cooldowns_npc y cooldowns_espacio. Si un valor es mayor que 0, restar 1. Si ya es 0, dejarlo en 0. No eliminar entradas cuando lleguen a 0. No tocar historial_eventos, etiquetas_activas, intensidad_dramatica_acumulada ni ratio_eventos_negativos. No depender de WorldState ni de crisis_fase."
}
